(function() {
  var container = element;
  if (!container) return;

  // Find the three column containers and separators
  var children = Array.from(container.children);
  var jornalismoCol = null;
  var esporteCol = null;
  var entretenimentoCol = null;
  var separators = [];

  for (var i = 0; i < children.length; i++) {
    var child = children[i];
    if (child.id === 'coluna-jornalismo') {
      jornalismoCol = child;
    } else if (child.id === 'coluna-esporte') {
      esporteCol = child;
    } else if (child.id === 'coluna-entretenimento') {
      entretenimentoCol = child;
    } else if (child.tagName === 'HR' && child.classList.contains('outer-separator')) {
      separators.push(child);
    }
  }

  // Only proceed if we found all three columns
  if (!jornalismoCol || !esporteCol || !entretenimentoCol) return;

  // Reorder: Entretenimento first, then Jornalismo, then Esporte
  // Clear container and re-append in new order
  while (container.firstChild) {
    container.removeChild(container.firstChild);
  }

  // Add entretenimento column first
  container.appendChild(entretenimentoCol);
  if (separators.length > 0) container.appendChild(separators[0]);
  // Then jornalismo
  container.appendChild(jornalismoCol);
  if (separators.length > 1) container.appendChild(separators[1]);
  // Then esporte
  container.appendChild(esporteCol);
})();

(function() {
  var body = element;
  if (!body) return;

  // Find the key sections
  var colunasSection = null;
  var hrAfterColunas = null;
  var videoBbbSection = null;
  var franjaVideoSection = null;

  var children = Array.from(body.children);

  for (var i = 0; i < children.length; i++) {
    var child = children[i];
    if (child.classList && child.classList.contains('area-colunas')) {
      colunasSection = child;
      // The HR after it should be the next sibling
      if (i + 1 < children.length && children[i + 1].tagName === 'HR') {
        hrAfterColunas = children[i + 1];
      }
    }
    if (child.classList && child.classList.contains('area-video-bbb')) {
      videoBbbSection = child;
    }
    if (child.id === 'franja-video') {
      franjaVideoSection = child;
    }
  }

  // Only proceed if we found the sections
  if (!colunasSection || !videoBbbSection || !franjaVideoSection) return;

  // Move video sections before the colunas section
  // First, remove them from their current positions
  var parent = videoBbbSection.parentNode;
  if (parent === body) {
    body.removeChild(videoBbbSection);
  }
  parent = franjaVideoSection.parentNode;
  if (parent === body) {
    body.removeChild(franjaVideoSection);
  }

  // Insert them before the colunas section
  body.insertBefore(videoBbbSection, colunasSection);
  body.insertBefore(franjaVideoSection, colunasSection);
})();
